/**
 * Personal project mutes: which projects a member does not want traffic from.
 */
import { and, asc, eq, sql } from "drizzle-orm";
import { getDb, projectMutes } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { brandId } from "./_mappers";
import { orgPredicate } from "./base-repository";
import type { OrgId, ProjectId, UserId } from "@/types/common";

/** The user's muted projects in this org, in the order they were muted. */
export async function listMutedProjectIds(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ProjectId[]> {
  const rows = getDb()
    .select({ projectId: projectMutes.projectId })
    .from(projectMutes)
    .where(
      and(
        orgPredicate(projectMutes.orgId, orgId),
        eq(projectMutes.userId, userId),
      ),
    )
    .orderBy(asc(sql`rowid`))
    .all();
  return rows.map((row) => brandId<ProjectId>(row.projectId));
}

/** Everyone in this org who has muted the project. */
export async function listUserIdsMutingProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly UserId[]> {
  const rows = getDb()
    .select({ userId: projectMutes.userId })
    .from(projectMutes)
    .where(
      and(
        orgPredicate(projectMutes.orgId, orgId),
        eq(projectMutes.projectId, projectId),
      ),
    )
    .all();
  return rows.map((row) => brandId<UserId>(row.userId));
}

/** Idempotent: muting an already-muted project is a no-op, not a conflict. */
export async function addProjectMute(
  orgId: OrgId,
  projectId: ProjectId,
  userId: UserId,
): Promise<void> {
  getDb()
    .insert(projectMutes)
    .values({
      orgId,
      projectId,
      userId,
      mutedAt: toIsoTimestamp(new Date()),
    })
    .onConflictDoNothing()
    .run();
}

/** Idempotent: lifting a mute that does not exist is a no-op. */
export async function removeProjectMute(
  orgId: OrgId,
  projectId: ProjectId,
  userId: UserId,
): Promise<void> {
  getDb()
    .delete(projectMutes)
    .where(
      and(
        orgPredicate(projectMutes.orgId, orgId),
        eq(projectMutes.projectId, projectId),
        eq(projectMutes.userId, userId),
      ),
    )
    .run();
}
